import fs from 'node:fs/promises';import path from 'node:path';import {createHash} from 'node:crypto';
const root=path.join(process.env.LOCALAPPDATA,'FVI-QA-Private-20260925','reference-metadata-contract-20261003'),out=path.resolve('scripts/qa/output/reference-metadata-contract-20261003');await fs.mkdir(root,{recursive:true});await fs.mkdir(out,{recursive:true});
const vault=await fs.readFile('./.private/CREDENTIALS.md','utf8'),a=vault.indexOf('<!-- FVI_CANONICAL_OPERATIONAL_CREDENTIALS_BEGIN -->'),b=vault.indexOf('<!-- FVI_CANONICAL_OPERATIONAL_CREDENTIALS_END -->');if(a<0||b<=a)throw Error('FVI canonical credential section missing');const token=vault.slice(a,b).split(/\r?\n/).find(x=>/^\|\s*`SUPABASE_ACCESS_TOKEN`\s*\|/.test(x))?.split('|')[2]?.trim().replace(/^`|`$/g,'');if(!/^sbp_[A-Za-z0-9_-]{20,}$/.test(token??''))throw Error('FVI readonly management credential unavailable');
const query=`SELECT jsonb_build_object(
'ledger',(SELECT jsonb_build_object('count',count(*),'latest',max(version::text)) FROM supabase_migrations.schema_migrations),
'engine',current_setting('server_version_num'),
'helpers',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'identity',pg_get_function_identity_arguments(p.oid),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'definition',pg_get_functiondef(p.oid),'md5',md5(replace(pg_get_functiondef(p.oid),E'\\r\\n',E'\\n'))) ORDER BY n.nspname,p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.prokind='f' AND ((n.nspname IN ('public','private') AND p.proname IN ('reference_scope_allows','get_data_resource_access_summary','data_resource_shadow_allows_actor','data_resource_shadow_allows','get_reference_table_view_summary')) OR (n.nspname='auth' AND p.proname IN ('uid','role','jwt')))),
'columns',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',at.attname,'position',at.attnum,'type',format_type(at.atttypid,at.atttypmod),'not_null',at.attnotnull) ORDER BY c.relname,at.attnum) FROM pg_attribute at JOIN pg_class c ON c.oid=at.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('reference_data_tables','data_resource_registry','data_resource_registry_owner_bu','data_resource_registry_grants','business_units','tenant_groups','tenant_members','tenant_group_members','bu_group_assignments','bu_user_assignments') AND at.attnum>0 AND NOT at.attisdropped),
'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY tablename,policyname) FROM pg_policies p WHERE schemaname='public' AND tablename IN ('reference_data_tables','data_resource_registry','data_resource_registry_owner_bu','data_resource_registry_grants','business_units','tenant_groups','tenant_members','tenant_group_members','bu_group_assignments','bu_user_assignments'))
) AS catalog;`;
await fs.writeFile(path.join(root,'catalog-readonly.sql'),query);const receipts=[];
for(const [environment,ref] of [['PROD','YOUR_PROJECT_REF'],['DEV','YOUR_PROJECT_REF']]){const r=await fetch('https://api.supabase.com/v1/projects/'+ref+'/database/query',{method:'POST',headers:{authorization:'Bearer '+token,'content-type':'application/json'},body:JSON.stringify({read_only:true,query}),signal:AbortSignal.timeout(30000)});if(!r.ok)throw Error(environment+' readonly catalog HTTP'+r.status+'; body withheld');const rows=await r.json(),cat=rows[0]?.catalog;if(!cat?.helpers||!cat?.columns)throw Error('Current catalog incomplete');const bytes=JSON.stringify({at:new Date().toISOString(),environment,ref,read_only:true,query,rows},null,2),file=path.join(root,environment+'-catalog.json');await fs.writeFile(file,bytes);const receipt={environment,file,sha256:createHash('sha256').update(bytes).digest('hex'),ledger:cat.ledger,engine:cat.engine,helpers:cat.helpers.map(h=>({schema:h.schema,name:h.name,identity:h.identity,md5:h.md5})),columns:cat.columns.length,policies:cat.policies.length};receipts.push(receipt);console.log(JSON.stringify(receipt));}
await fs.writeFile(path.join(out,'READONLY_CATALOG_RECEIPTS.json'),JSON.stringify(receipts,null,2));
